#!/usr/bin/env python3
from __future__ import annotations

import html
import json
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CONTRACT = ROOT / "automation/CEW_B1_HUMAN_ACCEPTANCE_CONTRACT_v2.json"
SESSION_KEY = "CEW_B1_HVA_V2_SESSION"


def _load(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def _esc(value) -> str:
    return html.escape(str(value or ""))


def task_specs() -> list[dict]:
    contract = _load(CONTRACT)
    starts = {
        "UX-DOC-01": "/",
        "UX-DOC-02": "/drawings/TAV-05A",
        "UX-DOC-03": "/evidence/review?task=ERW-N12-001",
        "UX-DOC-04": "/drawings/TAV-05A",
    }
    prompts = []
    for row in contract["tasks"]:
        prompt = {
            "task_id": row["task_id"],
            "prompt": row["participant_prompt_it"],
            "start_path": starts[row["task_id"]],
        }
        if row.get("post_task_mental_model_question_it"):
            prompt["mental_question"] = row["post_task_mental_model_question_it"]
        prompts.append(prompt)
    return prompts


TEMPLATE = r'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CEW — Verifica del percorso documentale</title>
<style>
:root{--ink:#17202a;--muted:#5d6875;--line:#d8dde3;--bg:#f3f5f7;--paper:#fff;--accent:#173f5f;--ok:#24613e;--bad:#a12622;--warn:#8a4b08}*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink)}a{color:var(--accent)}button,input,select,textarea{font:inherit}button{border:1px solid #b9c4cd;border-radius:8px;padding:10px 14px;background:#fff;color:var(--ink);font-weight:750;cursor:pointer}button.primary{background:var(--accent);border-color:var(--accent);color:#fff}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #ffbf47;outline-offset:2px}button:disabled{opacity:.45;cursor:not-allowed}header{background:#fff;border-bottom:1px solid var(--line)}.top{max-width:1500px;margin:auto;padding:16px 22px;display:flex;gap:16px;align-items:center}.brand{font-size:12px;font-weight:850;letter-spacing:.06em;color:var(--accent)}h1{font-size:24px;margin:2px 0}.muted{color:var(--muted)}main{max-width:1500px;margin:auto;padding:18px 22px 34px}.participant{display:grid;grid-template-columns:360px minmax(0,1fr);gap:14px}.task-card,.review-card,.complete-card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:20px}.progress{font-size:14px;color:var(--muted);margin-bottom:14px}.prompt{font-size:22px;line-height:1.35;margin:8px 0 18px}.support{border-top:1px solid #edf0f2;margin-top:18px;padding-top:14px}.hint{margin-top:10px;background:#fff7e8;border-left:4px solid var(--warn);padding:10px;display:none}.actions{display:flex;gap:8px;flex-wrap:wrap}.workspace{height:calc(100vh - 130px);min-height:610px;border:1px solid var(--line);border-radius:12px;background:#fff;overflow:hidden}.workspace iframe{border:0;width:100%;height:100%}.post{max-width:720px;margin:30px auto;background:#fff;border:1px solid var(--line);border-radius:12px;padding:24px}.post label,.review-card label{display:block;font-weight:700;margin:14px 0}.post select,.post textarea,.review-card select,.review-card input,.review-card textarea{display:block;width:100%;padding:10px;border:1px solid #c7d0d7;border-radius:7px;margin-top:5px;background:#fff}.post textarea,.review-card textarea{min-height:90px;resize:vertical}.choice{display:grid;gap:8px;margin:12px 0}.choice label{display:flex;gap:9px;align-items:flex-start;font-weight:600;margin:0;padding:10px;border:1px solid #e0e4e7;border-radius:8px}.complete-card{max-width:760px;margin:60px auto}.review-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(360px,.7fr);gap:14px}.review-card h2{margin-top:0}.task-result{border-top:1px solid #edf0f2;padding:14px 0}.task-result:first-of-type{border-top:0}.pill{display:inline-block;border-radius:999px;padding:4px 8px;background:#edf3f7;font-size:12px;margin:2px 4px 2px 0}.pill.bad{background:#fdebea;color:var(--bad)}.pill.ok{background:#eaf5ed;color:var(--ok)}.blockers{border-left:5px solid var(--bad);background:#fff1f0;padding:12px}.clear{border-left:5px solid var(--ok);background:#eef8f1;padding:12px}.technical{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;overflow-wrap:anywhere}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px){.participant,.review-layout{grid-template-columns:1fr}.workspace{height:65vh;min-height:480px}.prompt{font-size:19px}.top{align-items:flex-start}}
</style></head><body><div id="app"></div>
<script>
const TASKS=__TASKS_JSON__;const CONTRACT=__CONTRACT_JSON__;const RUNTIME_REVISION=__COMMIT_JSON__;const RUNTIME_DEPLOYMENT=__DEPLOYMENT_JSON__;const SESSION_KEY=__SESSION_KEY_JSON__;
const app=document.getElementById('app');let active=null;let startAt=0;let timer=null;let frame=null;let observer=null;
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function freshSession(){return{schema_version:'2.0',session_type:'CEW_B1_HUMAN_ACCEPTANCE_PARTICIPANT',started_at:new Date().toISOString(),runtime_revision:RUNTIME_REVISION,runtime_deployment:RUNTIME_DEPLOYMENT,task_results:{},participant_complete:false,canonical_write_authorized:false,engineering_authority_effect:'NONE'}}
function loadSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY))||freshSession()}catch(_e){return freshSession()}}
function saveSession(s){localStorage.setItem(SESSION_KEY,JSON.stringify(s))}
function resetSession(){const s=freshSession();saveSession(s);return s}
function currentIndex(){const s=loadSession();return TASKS.findIndex(t=>!s.task_results[t.task_id])}
function participantHeader(){return `<header><div class="top"><a href="/">← Progetto</a><div><div class="brand">CEW · VERIFICA DEL PERCORSO DOCUMENTALE</div><h1>Documenti, tavole ed evidenze</h1><div class="muted">Svolgi il lavoro come faresti normalmente. Non stai sostenendo un esame.</div></div></div></header>`}
function renderParticipant(){let s=loadSession();let i=currentIndex();if(i<0){s.participant_complete=true;s.completed_at=s.completed_at||new Date().toISOString();saveSession(s);return renderComplete()}const t=TASKS[i];active={task:t,task_index:i,started:false,metrics:{time_on_task_seconds:0,interaction_count:0,help_requests:0,backtracks_or_recovery_actions:0,navigation_path:[],viewer_states:[]},seen:new Set()};app.innerHTML=participantHeader()+`<main class="participant"><section class="task-card"><div class="progress">Attività ${i+1} di ${TASKS.length}</div><div class="prompt">${esc(t.prompt)}</div><p class="muted">Quando sei pronto, inizia. Il sistema registra in modo discreto solo ciò che serve a capire se il percorso funziona.</p><div class="actions"><button class="primary" id="start">Inizia</button><button id="done" disabled>Ho completato l’attività</button></div><div class="support"><button id="help" disabled>Mostra un suggerimento</button><div id="hint" class="hint"></div></div><div id="status" class="visually-hidden" aria-live="polite"></div></section><section class="workspace" aria-label="Spazio di lavoro CEW"><iframe id="journey" title="Spazio di lavoro CEW" src="about:blank"></iframe></section></main>`;frame=document.getElementById('journey');document.getElementById('start').onclick=startTask;document.getElementById('done').onclick=finishTask;document.getElementById('help').onclick=showHint;frame.addEventListener('load',onFrameLoad)}
function startTask(){if(!active||active.started)return;active.started=true;startAt=Date.now();active.metrics.navigation_path=[];active.metrics.viewer_states=[];document.getElementById('start').disabled=true;document.getElementById('done').disabled=false;document.getElementById('help').disabled=false;frame.src=active.task.start_path;timer=setInterval(()=>{active.metrics.time_on_task_seconds=Math.round((Date.now()-startAt)/1000)},500);document.getElementById('status').textContent='Attività iniziata'}
function showHint(){if(!active||!active.started)return;active.metrics.help_requests++;const hints={
'UX-DOC-01':'Usa gli accessi di lavoro del progetto come faresti normalmente. Non servono codici tecnici.',
'UX-DOC-02':'Puoi usare i controlli della vista per rendere la tavola leggibile e poi tornare alla vista iniziale.',
'UX-DOC-03':'Cerca il collegamento tra evidenza e contesto della tavola, poi prova a tornare al punto di partenza.',
'UX-DOC-04':'Osserva come CEW distingue il documento originale dagli ausili preparati per leggerlo meglio.'};const box=document.getElementById('hint');box.textContent=hints[active.task.task_id]||'Usa il percorso che ti sembra più naturale.';box.style.display='block'}
function onFrameLoad(){if(!active||!active.started)return;let path='UNREADABLE_FRAME_LOCATION';try{path=frame.contentWindow.location.pathname+frame.contentWindow.location.search}catch(_e){};active.metrics.navigation_path.push(path);if(active.seen.has(path))active.metrics.backtracks_or_recovery_actions++;active.seen.add(path);try{const doc=frame.contentDocument;doc.addEventListener('click',()=>{if(active&&active.started)active.metrics.interaction_count++},true);const state=doc.getElementById('viewerState');if(state){recordViewerState(state.textContent);if(observer)observer.disconnect();observer=new MutationObserver(()=>recordViewerState(state.textContent));observer.observe(state,{childList:true,subtree:true,characterData:true})}}catch(_e){}}
function recordViewerState(text){if(!active)return;const value=String(text||'').trim();if(value&&active.metrics.viewer_states[active.metrics.viewer_states.length-1]!==value)active.metrics.viewer_states.push(value)}
function taskOutcome(t,m){const paths=m.navigation_path;const last=paths[paths.length-1]||'';if(t.task_id==='UX-DOC-01')return paths.some(p=>p.startsWith('/drawings/TAV-05A'))?'SUCCESS':'FALSE_SUCCESS';if(t.task_id==='UX-DOC-02'){const rotated=m.viewer_states.some(v=>/Viewer (90|180|270)°/.test(v));const reset=/Viewer 0°/.test(m.viewer_states[m.viewer_states.length-1]||'');return rotated&&reset&&last.startsWith('/drawings/TAV-05A')?'SUCCESS':'FALSE_SUCCESS'}if(t.task_id==='UX-DOC-03'){const evidence=paths.findIndex(p=>p.startsWith('/evidence/review?task=ERW-N12-001'));const drawing=paths.findIndex((p,idx)=>idx>evidence&&p.startsWith('/drawings/TAV-05A'));return evidence>=0&&drawing>evidence?'SUCCESS':'FALSE_SUCCESS'}if(t.task_id==='UX-DOC-04')return 'PENDING_MENTAL_MODEL';return 'UNRESOLVED'}
function finishTask(){if(!active||!active.started)return;clearInterval(timer);active.metrics.time_on_task_seconds=Math.max(1,Math.round((Date.now()-startAt)/1000));try{const state=frame.contentDocument&&frame.contentDocument.getElementById('viewerState');if(state)recordViewerState(state.textContent)}catch(_e){};if(observer){observer.disconnect();observer=null}active.started=false;renderPostTask()}
function renderPostTask(){const t=active.task;const outcome=taskOutcome(t,active.metrics);let mental='';if(t.task_id==='UX-DOC-02')mental=`<fieldset><legend><b>${esc(t.mental_question||'Secondo te, hai modificato il documento originale?')}</b></legend><div class="choice"><label><input type="radio" name="mental" value="DISPLAY_VIEW_ONLY"> No, ho modificato solo la vista</label><label><input type="radio" name="mental" value="SOURCE_CHANGED"> Sì, ho modificato il documento originale</label><label><input type="radio" name="mental" value="NOT_SURE"> Non sono sicuro</label></div></fieldset>`;if(t.task_id==='UX-DOC-03')mental=`<fieldset><legend><b>Sei riuscito a vedere il contesto completo della tavola e poi a tornare all’evidenza?</b></legend><div class="choice"><label><input type="radio" name="mental" value="ROUND_TRIP_UNDERSTOOD"> Sì</label><label><input type="radio" name="mental" value="ROUND_TRIP_NOT_UNDERSTOOD"> No</label><label><input type="radio" name="mental" value="NOT_SURE"> Non sono sicuro</label></div></fieldset>`;if(t.task_id==='UX-DOC-04')mental=`<fieldset><legend><b>Quale useresti come fonte da verificare o citare?</b></legend><div class="choice"><label><input type="radio" name="mental" value="PRIMARY_PDF"> Il PDF originale verificato</label><label><input type="radio" name="mental" value="DERIVED_AID"> L’immagine preparata per la lettura</label><label><input type="radio" name="mental" value="EQUIVALENT"> Sono equivalenti</label><label><input type="radio" name="mental" value="NOT_SURE"> Non sono sicuro</label></div></fieldset>`;app.innerHTML=participantHeader()+`<main><section class="post"><div class="progress">Attività ${active.task_index+1} di ${TASKS.length}</div><h2>Com’è andata?</h2>${mental}<label>Quanto ti è sembrato semplice?<select id="ease"><option value="">— scegli —</option><option value="1">1 — molto difficile</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5 — molto semplice</option></select></label><label>Quanto sei sicuro di aver concluso correttamente?<select id="confidence"><option value="">— scegli —</option><option value="1">1 — per niente sicuro</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5 — molto sicuro</option></select></label><label>Se vuoi, indica cosa ti ha creato difficoltà<textarea id="comment"></textarea></label><button class="primary" id="continue">Continua</button></section></main>`;document.getElementById('continue').onclick=()=>savePostTask(outcome)}
function savePostTask(outcome){const ease=Number(document.getElementById('ease').value),confidence=Number(document.getElementById('confidence').value);if(ease<1||ease>5||confidence<1||confidence>5)return alert('Indica facilità e sicurezza da 1 a 5.');const mental=document.querySelector('input[name="mental"]:checked');if(['UX-DOC-02','UX-DOC-03','UX-DOC-04'].includes(active.task.task_id)&&!mental)return alert('Rispondi anche alla domanda sull’attività.');let finalOutcome=outcome;const mentalValue=mental?mental.value:null;if(active.task.task_id==='UX-DOC-04')finalOutcome=mentalValue==='PRIMARY_PDF'?'SUCCESS':'FALSE_SUCCESS';if(active.task.task_id==='UX-DOC-02'&&mentalValue!=='DISPLAY_VIEW_ONLY')finalOutcome='FALSE_SUCCESS';if(active.task.task_id==='UX-DOC-03'&&mentalValue!=='ROUND_TRIP_UNDERSTOOD')finalOutcome='FALSE_SUCCESS';const result={task_id:active.task.task_id,task_outcome:finalOutcome,...active.metrics,ease_1_to_5:ease,confidence_correct_1_to_5:confidence,mental_model_response:mentalValue,free_comment:document.getElementById('comment').value};const s=loadSession();s.task_results[active.task.task_id]=result;saveSession(s);active=null;renderParticipant()}
function renderComplete(){app.innerHTML=participantHeader()+`<main><section class="complete-card"><h2>Attività completate</h2><p>Grazie. Hai concluso la verifica del percorso Documenti, Tavole ed Evidenze.</p><p class="muted">Non devi valutare il rilascio del prodotto e non devi esportare alcun file. La revisione dei risultati avviene in un’area separata.</p><a href="/">Torna al progetto</a></section></main>`}
function deriveBlockers(s){const out=[];for(const t of TASKS){const r=s.task_results[t.task_id];if(!r){out.push(t.task_id+':NOT_OBSERVED');continue}if(r.task_outcome==='FALSE_SUCCESS')out.push(t.task_id+':FALSE_SUCCESS');if(t.task_id==='UX-DOC-02'&&r.mental_model_response!=='DISPLAY_VIEW_ONLY')out.push(t.task_id+':VIEWER_STATE_MISREAD_AS_SOURCE_MUTATION');if(t.task_id==='UX-DOC-03'&&r.mental_model_response!=='ROUND_TRIP_UNDERSTOOD')out.push(t.task_id+':PROVENANCE_BREAK');if(t.task_id==='UX-DOC-04'&&r.mental_model_response!=='PRIMARY_PDF')out.push(t.task_id+':PRIMARY_DERIVED_AUTHORITY_CONFUSION')}return [...new Set(out)]}
function deriveResiduals(s){const out=[];for(const t of TASKS){const r=s.task_results[t.task_id];if(!r)continue;if(r.help_requests>0)out.push(`${t.task_id}:HELP_USED_${r.help_requests}`);if(r.backtracks_or_recovery_actions>0)out.push(`${t.task_id}:RECOVERY_${r.backtracks_or_recovery_actions}`);if(r.ease_1_to_5<=2)out.push(`${t.task_id}:LOW_EASE_${r.ease_1_to_5}`)}return out}
function renderReviewer(){const s=loadSession();const blockers=deriveBlockers(s),residuals=deriveResiduals(s);const rows=TASKS.map(t=>{const r=s.task_results[t.task_id];if(!r)return `<div class="task-result"><b>${esc(t.task_id)}</b><p>Non osservato.</p></div>`;return `<div class="task-result"><b>${esc(t.task_id)}</b> <span class="pill ${r.task_outcome==='SUCCESS'?'ok':'bad'}">${esc(r.task_outcome)}</span><div><span class="pill">${r.time_on_task_seconds}s</span><span class="pill">${r.interaction_count} interazioni</span><span class="pill">${r.help_requests} aiuti</span><span class="pill">${r.backtracks_or_recovery_actions} recuperi</span><span class="pill">facilità ${r.ease_1_to_5}/5</span><span class="pill">sicurezza ${r.confidence_correct_1_to_5}/5</span></div><p><b>Modello mentale:</b> ${esc(r.mental_model_response||'non previsto')}</p><p><b>Percorso:</b> <span class="technical">${esc((r.navigation_path||[]).join(' → '))}</span></p>${r.viewer_states&&r.viewer_states.length?`<p><b>Stati viewer:</b> <span class="technical">${esc(r.viewer_states.join(' → '))}</span></p>`:''}${r.free_comment?`<p><b>Commento:</b> ${esc(r.free_comment)}</p>`:''}</div>`}).join('');const complete=TASKS.every(t=>s.task_results[t.task_id]);app.innerHTML=`<header><div class="top"><a href="/acceptance/b1">← Area partecipante</a><div><div class="brand">CEW · AREA REVISIONE HVA</div><h1>Revisione Human Acceptance B1.8</h1><div class="muted">Questa area è destinata al revisore, non al partecipante.</div></div></div></header><main class="review-layout"><section class="review-card"><h2>Evidenza raccolta</h2>${rows}</section><section class="review-card"><h2>Decisione del revisore</h2><p class="technical"><b>Revisione:</b> ${esc(RUNTIME_REVISION)}<br><b>Ambiente:</b> ${esc(RUNTIME_DEPLOYMENT)}</p>${blockers.length?`<div class="blockers"><b>Blocker critici</b><ul>${blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="clear"><b>Nessun blocker critico rilevato automaticamente.</b></div>`}${residuals.length?`<h3>Residui di usabilità</h3><ul>${residuals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<label>Decisione HVA<select id="decision" ${complete?'':'disabled'}><option value="">— seleziona —</option>${CONTRACT.reviewer_decisions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Revisore<input id="reviewer" ${complete?'':'disabled'}></label><label>Osservazioni<textarea id="note" ${complete?'':'disabled'}></textarea></label><button class="primary" id="export" ${complete?'':'disabled'}>Esporta receipt HVA</button><p class="muted">L’esportazione produce evidenza di accettazione legata alla revisione. Non modifica dati ingegneristici e non promuove automaticamente B1.</p><button id="reset">Azzera sessione di test</button></section></main>`;document.getElementById('export').onclick=()=>exportReceipt(s,blockers,residuals);document.getElementById('reset').onclick=()=>{if(confirm('Azzerare i risultati della sessione locale?')){resetSession();location.hash='';renderParticipant()}}}
function exportReceipt(s,blockers,residuals){const decision=document.getElementById('decision').value,reviewer=document.getElementById('reviewer').value.trim();if(!decision||!reviewer)return alert('Decisione HVA e revisore sono obbligatori.');if(blockers.length&&decision!=='FAIL_REWORK_REQUIRED')return alert('Sono presenti blocker critici: la decisione deve essere FAIL_REWORK_REQUIRED.');const receipt={schema_version:'2.0',receipt_type:'CEW_B1_HUMAN_ACCEPTANCE_V2',generated_at:new Date().toISOString(),runtime_revision:RUNTIME_REVISION,runtime_deployment:RUNTIME_DEPLOYMENT,benchmark_version:'B1.8-v2',participant_session_started_at:s.started_at,participant_session_completed_at:s.completed_at||null,task_results:TASKS.map(t=>s.task_results[t.task_id]),critical_blockers:blockers,usability_residuals:residuals,human_hva_decision:decision,human_reviewer:reviewer,human_note:document.getElementById('note').value,production_smoke_required:true,production_smoke_state:'REQUIRED_NOT_SATISFIED',slice_complete:false,promotion_authorized:false,canonical_write_authorized:false,engineering_authority_effect:'NONE'};const blob=new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CEW_B1_HUMAN_ACCEPTANCE_V2_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();URL.revokeObjectURL(a.href)}
function route(){if(location.hash==='#review')renderReviewer();else renderParticipant()}window.addEventListener('hashchange',route);route();
</script></body></html>'''


def build_app() -> str:
    contract = _load(CONTRACT)
    tasks = task_specs()
    commit = os.getenv("VERCEL_GIT_COMMIT_SHA") or os.getenv("GITHUB_SHA") or "UNRESOLVED_RUNTIME_REVISION"
    deployment = os.getenv("VERCEL_URL") or "LOCAL_OR_UNRESOLVED_DEPLOYMENT"
    return (
        TEMPLATE
        .replace("__TASKS_JSON__", json.dumps(tasks, ensure_ascii=False).replace("</", "<\\/"))
        .replace("__CONTRACT_JSON__", json.dumps({"reviewer_decisions": contract["reviewer_decisions"]}, ensure_ascii=False).replace("</", "<\\/"))
        .replace("__COMMIT_JSON__", json.dumps(commit))
        .replace("__DEPLOYMENT_JSON__", json.dumps(deployment))
        .replace("__SESSION_KEY_JSON__", json.dumps(SESSION_KEY))
    )


if __name__ == "__main__":
    print(build_app())
